/* Function for MATLAB Function: '<Root>/ElectricalDetector' */
static real_T MotorFaultDeploy_mean_g(const real_T x[2400])
{
  real_T b_y;
  real_T bsum;
  int32_T b_k;
  int32_T counts;
  int32_T k;
  if (rtIsNaN(x[0])) {
    b_y = 0.0;
    counts = 0;
  } else {
    b_y = x[0];
    counts = 1;
  }

  for (k = 0; k < 1023; k++) {
    bsum = x[k + 1];
    if (!rtIsNaN(bsum)) {
      b_y += bsum;
      counts++;
    }
  }

  for (k = 0; k < 2; k++) {
    int32_T hi;
    int32_T xblockoffset;
    xblockoffset = (k + 1) << 10;
    bsum = x[xblockoffset];
    if (rtIsNaN(bsum)) {
      bsum = 0.0;
    } else {
      counts++;
    }

    if (k + 2 == 3) {
      hi = 352;
    } else {
      hi = 1024;
    }

    for (b_k = 2; b_k <= hi; b_k++) {
      int32_T xoffset;
      xoffset = (xblockoffset + b_k) - 1;
      if (!rtIsNaN(x[xoffset])) {
        bsum += x[xoffset];
        counts++;
      }
    }

    b_y += bsum;
  }

  return b_y / (real_T)counts;
}

/* Function for MATLAB Function: '<Root>/ElectricalDetector' */
static real_T MotorFaul_combineVectorElements(const real_T x[2400])
{
  real_T y;
  int32_T b_k;
  int32_T k;
  y = x[0];
  for (k = 0; k < 1023; k++) {
    y += x[k + 1];
  }

  for (k = 0; k < 2; k++) {
    real_T bsum;
    int32_T hi;
    int32_T xblockoffset;
    xblockoffset = (k + 1) << 10;
    bsum = x[xblockoffset];
    if (k + 2 == 3) {
      hi = 352;
    } else {
      hi = 1024;
    }

    for (b_k = 2; b_k <= hi; b_k++) {
      bsum += x[(xblockoffset + b_k) - 1];
    }

    y += bsum;
  }

  return y;
}

